void GetNamedProperty(v8::Local<v8::Name> name, const v8::PropertyCallbackInfo<v8::Value>& info) {
  // Convert the property name to a string
  v8::Local<v8::String> v8_name;
  if (!name->ToString(info.GetIsolate()).ToLocal(&v8_name)) {
    return;
  }

  // Convert the v8 string to a UTF-8 string
  v8::String::Utf8Value utf8_name(v8_name);
  if (!utf8_name) {
    return;
  }

  // Retrieve the LocalDOMWindow
  LocalDOMWindow* window = ToLocalDOMWindow(info.Holder());
  if (!window) {
    return;
  }

  // Check if the window is attached to a frame
  Frame* frame = window->GetFrame();
  if (!frame) {
    return;
  }

  // Search for sub-frames
  v8::Local<v8::Value> result;
  if (frame->FindSubFrame(*utf8_name, &result)) {
    info.GetReturnValue().Set(result);
    return;
  }

  // Search for named items in the document
  if (frame->GetDocument()->FindNamedItem(*utf8_name, &result)) {
    info.GetReturnValue().Set(result);
    return;
  }

  // If no matching item is found, return undefined
  info.GetReturnValue().Set(v8::Undefined(info.GetIsolate()));
}
